 async function upload(file:File,folder:"avatar"|"post"){if(!supabase||!user)return null;if(!["image/jpeg","image/png","image/webp"].includes(file.type)){setError("Choose a JPG, PNG, or WebP image.");return null}if(file.size>10*1024*1024){setError("Images must be 10 MB or smaller.");return null}const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,"_");const path=folder==="avatar"?`${user.id}/avatar-${Date.now()}.${ext(file)}`:`${user.id}/posts/${crypto.randomUUID()}-${safe}`;const r=await supabase.storage.from("wayss-media").upload(path,file,{cacheControl:"3600",upsert:false,contentType:file.type||undefined});if(r.error){setError(r.error.message);return null}return supabase.storage.from("wayss-media").getPublicUrl(path).data.publicUrl}
