 async function signup(){if(!supabase){setAuthMsg("WAYSS authentication is not configured.");return}const username=emailUsername.trim().replace(/^@/,"").toLowerCase();const signupEmail=email.trim().toLowerCase();if(!/^[a-z0-9._]{3,24}$/.test(username)){setAuthMsg("Create a username first (3–24 characters: letters, numbers, dots or underscores).");return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(signupEmail)){setAuthMsg("Enter a valid email address.");return}if(password.length<8){setAuthMsg("Use at least 8 characters for a safer password.");return}const{data:existing,error:checkError}=await supabase.from("profiles").select("id").eq("username",username).maybeSingle();if(checkError){setAuthMsg("Could not check username: "+checkError.message);return}if(existing){setAuthMsg("That username is already taken. Try another.");return}const{data,error}=await supabase.auth.signUp({email:signupEmail,password,options:{data:{username},emailRedirectTo:window.location.origin}});if(error){const m=error.message.toLowerCase();setAuthMsg(m.includes("rate limit")||m.includes("email")&&m.includes("send")?"Supabase could not send the confirmation email. Try Resend confirmation below; if it still fails, the project email/SMTP limit must be fixed in Supabase Auth settings.":error.message);return}if(data.user&&data.session){const{error:profileError}=await supabase.from("profiles").upsert({id:data.user.id,username},{onConflict:"id"});if(profileError){setAuthMsg("Account was created and signed in, but profile setup needs attention: "+profileError.message);return}}setAuthMsg(data.session?"Account created and signed in. Welcome to WAYSS!":"Account created. Check your inbox and spam folder for the confirmation link. You can resend it below.");}
