 async function like(p:Post){if(!user){setAuth(true);return}const n=!p.liked;setPosts(a=>a.map(x=>x.id===p.id?{...x,liked:n,likes:Math.max(0,x.likes+(n?1:-1))}:x));const r=n?await supabase!.from("post_likes").insert({post_id:p.id,user_id:user.id}):await supabase!.from("post_likes").delete().eq("post_id",p.id).eq("user_id",user.id);if(r.error)loadPosts()}
