 async function uploadFlux(file:File,caption="",song=""){if(!user){setAuth(true);return}if(!file.type.startsWith("video/")){setFluxError("Please select a video file.");return}if(file.size>100*1024*1024){setFluxError("Video must be 100 MB or smaller.");return}setFluxUploading(true);setFluxError("");const path=`${user.id}/flux/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,"_")}`;const{error}=await supabase!.storage.from("wayss-media").upload(path,file,{contentType:file.type,upsert:false});if(error){setFluxError(error.message);setFluxUploading(false);return}const media_url=supabase!.storage.from("wayss-media").getPublicUrl(path).data.publicUrl;const{error:postError}=await supabase!.from("posts").insert({author_id:user.id,kind:"flux",body:[caption.trim(),song.trim()?`♪ ${song.trim()}`:""].filter(Boolean).join("\n")||null,media_url,audience:"public"});if(postError){setFluxError(postError.message);await supabase!.storage.from("wayss-media").remove([path]);setFluxUploading(false);return}setFluxUploading(false);await loadFlux()}
 async function loadPeople(contactPhones:string[]=[],searchTerm:string=""){
  if(!supabase||!user)return;
  setPeopleBusy(true);setPeopleError("");
  let ps:any[]=[];
  if(searchTerm){
   const term=searchTerm.trim().replace(/^@/,"").replace(/[%,()."'\\]/g," ").replace(/\s+/g," ").trim();
   if(!term){setPeople([]);setPeopleBusy(false);return;}
   const {data,error}=await supabase.from("profiles").select("id,username,display_name,bio,avatar_url,is_private,active_status,created_at,is_verified").neq("id",user.id).eq("active_status",true).or(`username.ilike.%${term}%,display_name.ilike.%${term}%`).order("username").limit(50);
   if(error){setPeopleError(error.message||"Could not search people");setPeopleBusy(false);return;}
   ps=data||[];
  }else{
   const {data,error}=await supabase.functions.invoke("orbit-suggestions",{body:{contactPhones}});
   if(error){setPeopleError(error.message||"Could not load relevant people");setPeopleBusy(false);return}
   ps=Array.isArray(data?.profiles)?data.profiles:[];
  }
  const {data:cs,error:ce}=await supabase.from("connections").select("follower_id,following_id,status").or(`follower_id.eq.${user.id},following_id.eq.${user.id}`);
  if(ce){setPeopleError(ce.message);setPeopleBusy(false);return}
  const rel=new Map<string,Person["relation"]>();
  (cs||[]).forEach((c:any)=>{if(c.follower_id===user.id)rel.set(c.following_id,c.status==="pending"?"pending_out":"connected");else rel.set(c.follower_id,c.status==="pending"?"pending_in":"connected")});
  setPeople(ps.filter((p:any)=>p.id!==user.id).map((p:any)=>({...p,relation:rel.get(p.id)||"none",count:0})));
  setPeopleBusy(false)
}
