 async function openList(type:"followers"|"following"){if(!supabase||!user)return;setListType(type);setListBusy(true);const key=type==="followers"?"follower_id":"following_id";const match=type==="followers"?"following_id":"follower_id";const{data,error}=await supabase.from("connections").select(key).eq(match,user.id).eq("status","accepted").limit(200);if(error){setListPeople([]);setListBusy(false);return}const ids=[...new Set((data||[]).map((x:any)=>x[key]).filter((id:string)=>id!==user.id))];if(!ids.length){setListPeople([]);setListBusy(false);return}const result=await supabase.from("profiles").select("id,username,display_name,avatar_url,is_verified").in("id",ids).order("username");setListPeople(result.data||[]);setListBusy(false)}
